{
  "message": "Implement batch validation and JSON-compatible serialization using Pydantic v2.",
  "rationale": "A discriminated union enforces event-specific fields and preserves indexed validation errors, while validation context keeps each cap local to its call. JSON-mode serialization emits aliases and precise Decimal strings, includes computed signed amounts, and omits None.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "from decimal import Decimal
from typing import Annotated, Literal, Union

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    TypeAdapter,
    ValidationInfo,
    computed_field,
    field_validator,
)


class Event(BaseModel):
    model_config = ConfigDict(extra='forbid', populate_by_name=True)

    kind: Literal['debit', 'credit']
    account_id: int = Field(alias='accountId', strict=True, gt=0)
    amount: Decimal = Field(gt=0, decimal_places=2, allow_inf_nan=False)
    currency: Literal['USD', 'EUR']

    @field_validator('amount')
    @classmethod
    def check_cap(cls, value: Decimal, info: ValidationInfo) -> Decimal:
        if info.context is not None and value > info.context['cap']:
            raise ValueError('amount exceeds cap')
        return value

    @computed_field
    @property
    def signed(self) -> Decimal:
        return self.amount.copy_negate() if self.kind == 'debit' else self.amount


class Debit(Event):
    kind: Literal['debit']
    reason: str = Field(min_length=3)


class Credit(Event):
    kind: Literal['credit']
    reference: str | None = None


_BATCH_ADAPTER = TypeAdapter(
    Annotated[
        list[Annotated[Union[Debit, Credit], Field(discriminator='kind')]],
        Field(strict=True),
    ]
)
_CAP_ADAPTER = TypeAdapter(
    Annotated[Decimal, Field(gt=0, allow_inf_nan=False)]
)


def parse_batch(payload, cap='100.00'):
    context = {'cap': _CAP_ADAPTER.validate_python(cap)}
    if isinstance(payload, (str, bytes)):
        return _BATCH_ADAPTER.validate_json(payload, context=context)
    return _BATCH_ADAPTER.validate_python(payload, context=context)


def dump_batch(events):
    return [
        event.model_dump(mode='json', by_alias=True, exclude_none=True)
        for event in events
    ]
